<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import GroupNodeList from '../components/GroupNodeList.vue';
import {filterGroupMembers} from '../lib/nodeGroups';
import {Package,Layers3,Plus,Pencil,RefreshCw,X,Search,Trash2} from 'lucide-vue-next';
import type {Plan,NodeGroup,GroupMember} from '../types';
import {useApi,isCancelled} from '../lib/api';
import {bytes} from '../lib/format';
import {cents,money} from '../lib/commerce';
import {t} from '../i18n';
import {usePanelContext} from '../composables/panelContext';
import {useModalFocus} from '../composables/useModalFocus';
import PlanNodeSelector from '../components/PlanNodeSelector.vue';
const route=useRoute();
const props=defineProps<{mode?:'plans'|'groups'}>();
const groupSearch=ref(''),groupSource=ref('all');
const groupRows=(id:string)=>filterGroupMembers(members.value[id]||[],groupSearch.value,groupSource.value);
const {state,simpleMode,publicFeaturesEnabled,confirmation}=usePanelContext(),api=useApi();
const plans=ref<Plan[]>([]),groups=ref<NodeGroup[]>([]),members=ref<Record<string,GroupMember[]>>({}),loaded=ref(false),busy=ref(false),error=ref(''),tab=ref(props.mode|| (route.query.tab==='groups'?'groups':'plans')),search=ref(''),category=ref(''),archived=ref(false);
watch(()=>route.query.tab,value=>{if(!props.mode)tab.value=value==='groups'?'groups':'plans';});
const editingPlan=ref<Plan|null>(null),editingGroup=ref<NodeGroup|null>(null),quotaGB=ref(0),unlimited=ref(false),priceYuan=ref('0.00'),dialog=ref<HTMLElement|null>(null);
const open=computed(()=>!!editingPlan.value||!!editingGroup.value);
const categories=computed(()=>[...new Set(plans.value.map(p=>p.category).filter(Boolean))].sort());
const filtered=computed(()=>plans.value.filter(p=>(archived.value||!p.archived)&&(!category.value||p.category===category.value)&&[p.name,p.description,p.category].join(' ').toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>a.sort-b.sort||a.name.localeCompare(b.name)));
const visibleGroups=computed(()=>[...groups.value].filter(g=>((simpleMode.value||!publicFeaturesEnabled.value)&&g.scope==='public')?false:true).sort((a,b)=>a.sort-b.sort||a.name.localeCompare(b.name)));
const cycleLabel=(cycle:string)=>cycle==='30d'?t('每 30 天'):cycle==='month'?t('每自然月'):t('不自动重置');
const pageTitle=computed(()=>tab.value==='groups'?t('节点组管理'):t('套餐管理'));
const pageSubtitle=computed(()=>tab.value==='groups'?t('独立维护节点分组，套餐只引用节点组和单独节点。'):t('套餐统一决定账号额度、有效期和节点权限。'));
function close(){if(!busy.value){editingPlan.value=null;editingGroup.value=null;error.value='';}}
useModalFocus(open,dialog,close);
async function load(){try{const [p,g]=await Promise.all([api<{plans:Plan[]}>('/plans'),api<{groups:NodeGroup[];members:Record<string,GroupMember[]>}>('/node-groups')]);plans.value=p.plans;groups.value=g.groups;members.value=g.members;loaded.value=true;}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}}
function editPlan(p?:Plan){error.value='';editingPlan.value=p?JSON.parse(JSON.stringify({...p,node_ids:p.node_ids||[]})):{id:'',version:0,name:'',description:'',category:'',notes:'',archived:false,sort:0,quota:100*1024**3,valid_days:30,cycle:'30d',timezone:'Asia/Shanghai',group_ids:[],node_ids:[],vless:true,hy2:true,price:'0',system:false};quotaGB.value=editingPlan.value!.quota/1024**3;unlimited.value=!editingPlan.value!.quota;priceYuan.value=(Number(editingPlan.value!.price||'0')/100).toFixed(2);}
function editGroup(g?:NodeGroup){error.value='';editingGroup.value=g?JSON.parse(JSON.stringify(g)):{id:'',name:'',description:'',scope:'private',enabled:true,sort:0,revision:''};}
async function save(){busy.value=true;error.value='';try{if(editingPlan.value){const price=priceYuan.value.trim()==='0'||priceYuan.value.trim()==='0.0'||priceYuan.value.trim()==='0.00'?'0':cents(priceYuan.value);const p={...editingPlan.value,price,quota:unlimited.value?0:Math.round(quotaGB.value*1024**3)};if(!unlimited.value&&p.quota<=0)throw new Error(t('有限额度必须大于 0'));await api('/plans','POST',p);}else if(editingGroup.value)await api('/node-groups','POST',editingGroup.value);editingPlan.value=null;editingGroup.value=null;await load();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
function deletePlan(p:Plan){confirmation.value={title:t('删除套餐')+' · '+p.name,detail:p.system?t('系统预置套餐不能删除。'):t('删除会立即移除套餐、版本和商品引用；已有用户权益与订单快照不会回滚。'),action:async()=>{await api('/plans/'+encodeURIComponent(p.id),'DELETE');await load();}};}
function deleteGroup(g:NodeGroup){confirmation.value={title:t('删除节点组')+' · '+g.name,detail:t('删除会立即移除节点组，套餐、用户和节点中的旧引用将失效，请确认这是有意的破坏性操作。'),action:async()=>{await api('/node-groups/'+encodeURIComponent(g.id),'DELETE');await load();}};}
onMounted(load);
</script>
<template>
<section class="plans-page">
 <header class="page-heading"><div><div class="eyebrow">{{tab==='groups'?'NODE GROUPS':'ENTITLEMENTS'}}</div><h1>{{pageTitle}}</h1><p class="section-subtitle">{{pageSubtitle}}</p></div><div class="plan-actions"><button :disabled="busy" @click="load"><RefreshCw :size="15"/>{{t('刷新')}}</button><button class="primary" @click="tab==='plans'?editPlan():editGroup()"><Plus :size="16"/>{{tab==='plans'?t('创建套餐'):t('创建节点组')}}</button></div></header>
 <div class="plan-stat-grid"><div><Package :size="19"/><span>{{t('可分配套餐')}}</span><strong>{{plans.filter(p=>!p.archived).length}}</strong></div><div><Layers3 :size="19"/><span>{{t('节点权限组')}}</span><strong>{{visibleGroups.length}}</strong></div><div><span>{{t('授权方式')}}</span><strong class="stat-text">{{t('按套餐自动授权')}}</strong><small>{{t('节点组和单独节点共同决定订阅内容')}}</small></div></div>
 <div v-if="!props.mode" class="plans-tabs" role="tablist" :aria-label="t('套餐管理')"><button role="tab" :aria-selected="tab==='plans'" :class="{active:tab==='plans'}" @click="tab='plans'"><Package :size="16"/>{{t('套餐列表')}}</button><button role="tab" :aria-selected="tab==='groups'" :class="{active:tab==='groups'}" @click="tab='groups'"><Layers3 :size="16"/>{{t('节点权限组')}}</button></div>
 <p v-if="error&&!open" class="error" role="alert">{{t(error)}}</p>
 <template v-if="tab==='plans'"><div class="toolbar"><div class="search"><Search :size="16"/><input v-model="search" :placeholder="t('搜索套餐')" :aria-label="t('搜索套餐')"/></div><select v-model="category" :aria-label="t('套餐分类')"><option value="">{{t('全部分类')}}</option><option v-for="c in categories" :key="c">{{c}}</option></select><label class="inline-check"><input v-model="archived" type="checkbox"/>{{t('显示已归档')}}</label></div>
 <div class="plan-cards"><article v-for="p in filtered" :key="p.id" class="plan-card"><header><span class="plan-icon"><Package :size="21"/></span><div><h2>{{p.name}}</h2><small>{{p.category||t('未分类')}} · v{{p.version}}</small></div><span class="spacer"/><button class="icon" :aria-label="t('编辑套餐')+' '+p.name" @click="editPlan(p)"><Pencil :size="16"/></button><button v-if="!p.system" class="icon danger-icon" :aria-label="t('删除套餐')+' '+p.name" @click="deletePlan(p)"><Trash2 :size="16"/></button></header><p class="plan-description">{{p.description||t('尚未填写套餐简介')}}</p><div class="plan-price">{{money(p.price)}}<small>{{t('套餐价格')}}</small></div><div class="plan-quota">{{p.quota?bytes(p.quota):t('不限')}}<small>{{t('配额用量')}} · {{cycleLabel(p.cycle)}}</small></div><dl><div><dt>{{t('有效期')}}</dt><dd>{{p.valid_days?p.valid_days+' '+t('天'):t('不限')}}</dd></div><div><dt>{{t('节点权限组')}}</dt><dd>{{p.group_ids.length}}</dd></div><div><dt>{{t('单独节点')}}</dt><dd>{{p.node_ids?.length||0}}</dd></div></dl><div class="plan-tags"><span v-if="p.vless" class="tag vless">VLESS</span><span v-if="p.hy2" class="tag hy2">HY2</span><span :class="['badge',p.archived?'neutral':'success']">{{p.archived?t('已归档'):t('可分配')}}</span></div><footer><span v-for="id in p.group_ids" :key="id">{{groups.find(g=>g.id===id)?.name||id}}</span><span v-for="id in (p.node_ids||[])" :key="'node:'+id">{{state?.nodes.find(n=>n.id===id)?.name||id}}</span></footer></article></div><div v-if="!filtered.length" class="empty"><Package :size="28"/><p>{{loaded?t('暂无套餐，创建后可在用户管理中分配。'):t('加载中…')}}</p></div></template>
 <template v-else><div class="toolbar"><div class="search"><Search :size="16"/><input v-model="groupSearch" :placeholder="t('搜索节点、站点、协议或 IP')" :aria-label="t('搜索组内节点')"/></div><select v-model="groupSource" :aria-label="t('节点来源')"><option value="all">{{t('全部来源')}}</option><option value="local">{{t('本站节点')}}</option><option value="mounted">{{t('子站挂载')}}</option><option value="public">{{t('公共节点')}}</option></select></div><p class="field-help">{{t('删除节点组会立即使旧引用失效，默认系统节点组仍受保护。')}}</p><div class="plan-cards"><article v-for="g in visibleGroups.filter(g=>(!groupSearch&&groupSource==='all')||groupRows(g.id).length)" :key="g.id" class="plan-card"><header><span class="plan-icon"><Layers3 :size="21"/></span><div><h2>{{g.name}}</h2><small>{{t('可混合本站、公共与挂载节点')}}</small></div><span class="spacer"/><button class="icon" :aria-label="t('编辑节点组')+' '+g.name" @click="editGroup(g)"><Pencil :size="16"/></button><button v-if="!['legacy-private','legacy-public','default-subsite'].includes(g.id)" class="icon danger-icon" :aria-label="t('删除节点组')+' '+g.name" @click="deleteGroup(g)"><Trash2 :size="16"/></button></header><p class="plan-description">{{g.description||t('尚未填写说明')}}</p><div class="plan-tags"><span :class="['badge',g.enabled?'success':'neutral']">{{g.enabled?t('已启用'):t('已停用')}}</span><span>{{groupRows(g.id).length}} {{t('个节点')}}</span></div><GroupNodeList :members="groupRows(g.id)"/><p v-if="!members[g.id]?.length" class="field-help">{{t('此组暂无节点，可在节点配置中加入。')}}</p></article></div></template>
 <Teleport to="body"><div v-if="open" class="modal-shade" @click.self="close"><form class="modal entitlement-editor" ref="dialog" tabindex="-1" role="dialog" aria-modal="true" :aria-label="editingPlan?t('套餐设置'):t('节点组设置')" @submit.prevent="save"><div class="modal-head"><h2>{{editingPlan?t('套餐设置'):t('节点组设置')}}</h2><button type="button" class="icon" :disabled="busy" :aria-label="t('关闭')" @click="close"><X :size="20"/></button></div>
 <template v-if="editingPlan"><p class="field-help">{{t('保存为新的模板版本。已有用户保留当前权益，应用新版本请到用户管理。')}}</p><label>{{t('套餐名称')}}<input v-model="editingPlan.name" maxlength="100" required/></label><div class="field-row"><label>{{t('套餐分类')}}<input v-model="editingPlan.category" list="plan-categories" maxlength="100"/><datalist id="plan-categories"><option v-for="c in categories" :key="c" :value="c"/></datalist></label><label>{{t('排序')}}<input v-model.number="editingPlan.sort" type="number" min="0" max="9999"/></label></div><label>{{t('套餐简介')}}<textarea v-model="editingPlan.description" maxlength="2000" rows="2"/></label><label>{{t('套餐价格 / 元')}}<input v-model="priceYuan" inputmode="decimal" placeholder="0.00" required/><small>{{t('用于套餐目录和新销售配置，订单会保存价格快照')}}</small></label><div class="field-row"><label>{{t('周期额度 / GiB')}}<input v-model.number="quotaGB" :disabled="unlimited" type="number" min="0.0001" step="any" required/></label><label>{{t('有效天数')}}<input v-model.number="editingPlan.valid_days" type="number" min="0" max="36500" required/><small>{{t('0 为不限')}}</small></label></div><label class="inline-check"><input v-model="unlimited" type="checkbox"/>{{t('不限额度')}}</label><div class="field-row"><label>{{t('配额周期')}}<select v-model="editingPlan.cycle"><option value="none">{{t('不自动重置')}}</option><option value="30d">{{t('每 30 天')}}</option><option value="month">{{t('每自然月')}}</option></select></label><label v-if="editingPlan.cycle==='month'">{{t('周期时区')}}<select v-model="editingPlan.timezone"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option><option>Asia/Singapore</option></select></label></div><PlanNodeSelector :groups="groups" :members="members" :nodes="state?.nodes||[]" :group-ids="editingPlan.group_ids" :node-ids="editingPlan.node_ids" :hide-public="simpleMode" @update:group-ids="editingPlan.group_ids=$event" @update:node-ids="editingPlan.node_ids=$event"/><div class="check-row"><label class="inline-check"><input v-model="editingPlan.vless" type="checkbox"/>VLESS</label><label class="inline-check"><input v-model="editingPlan.hy2" type="checkbox"/>HY2</label><label class="inline-check"><input v-model="editingPlan.archived" type="checkbox"/>{{t('归档套餐')}}</label></div><label v-if="!simpleMode">{{t('管理员备注')}}<textarea v-model="editingPlan.notes" rows="2" maxlength="2000"/></label></template>
 <template v-if="editingGroup"><label>{{t('节点组名称')}}<input v-model="editingGroup.name" maxlength="100" required/></label><label>{{t('说明')}}<textarea v-model="editingGroup.description" rows="3" maxlength="1000"/></label><div class="field-row"><label>{{t('排序')}}<input v-model.number="editingGroup.sort" type="number" min="0" max="9999"/></label></div><label class="inline-check"><input v-model="editingGroup.enabled" type="checkbox"/>{{t('启用节点组')}}</label><p class="field-help">{{t('停用会撤销此组的线路权限；用户仍可使用其他获授权的组。')}}</p></template>
 <p v-if="error" class="error" role="alert">{{t(error)}}</p><div class="modal-footer"><button type="button" :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy">{{busy?t('保存中…'):t('保存设置')}}</button></div></form></div></Teleport>
</section>
</template>
<style scoped>
.plans-page{display:flex;flex-direction:column;gap:22px}.plans-page .page-heading{margin:0}.plan-actions,.plan-tags{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.plan-stat-grid{display:grid;grid-template-columns:1fr 1fr 1.4fr;gap:16px}.plan-stat-grid>div{display:flex;flex-direction:column;gap:9px;padding:20px;border:1px solid var(--border);border-radius:12px;background:var(--surface)}.plan-stat-grid svg{color:var(--accent-text)}.plan-stat-grid span,.plan-stat-grid small{font-size:12px;color:var(--muted)}.plan-stat-grid strong{font-size:27px}.plan-stat-grid .stat-text{font-size:19px}.plans-tabs{display:flex;gap:24px;border-bottom:1px solid var(--border)}.plans-tabs button{border:0;border-radius:0;background:none;padding:12px 0;color:var(--muted)}.plans-tabs .active{border-bottom:2px solid var(--accent);color:var(--accent-text)}.plan-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,290px),1fr));gap:18px}.plan-card{border:1px solid var(--border);border-radius:13px;background:var(--surface);padding:22px;min-width:0}.plan-card header{display:flex;align-items:center;gap:12px}.plan-icon{padding:10px;border-radius:10px;background:var(--surface-hover);color:var(--accent-text);display:flex}.plan-card h2{font-size:16px;margin:0 0 5px;overflow-wrap:anywhere}.plan-card small,.plan-description{font-size:12px;color:var(--muted)}.plan-description{line-height:1.7;min-height:40px;margin:18px 0}.plan-price{font-size:22px;font-weight:650;margin-bottom:12px}.plan-price small{display:block;font-size:12px;font-weight:400;color:var(--muted);margin-top:5px}.plan-quota{font-size:26px;font-weight:650;letter-spacing:-.6px}.plan-quota small{display:block;font-weight:400;letter-spacing:0;margin-top:7px}.plan-card dl{margin:22px 0;display:flex;gap:25px}.plan-card dl div{flex:1}.plan-card dt{font-size:11px;color:var(--muted)}.plan-card dd{margin:7px 0 0;font-size:13px;font-weight:600}.plan-card footer{display:flex;gap:6px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:14px;margin-top:18px}.plan-card footer span{font-size:11px;border-radius:5px;padding:4px 7px;background:var(--surface-hover);color:var(--muted)}.inline-check{display:flex;flex-direction:row;align-items:center;gap:8px;font-size:13px;margin:0}.inline-check input{width:16px;height:16px;margin:0}.group-members{padding:0;list-style:none;max-height:220px;overflow:auto}.group-members li{display:flex;flex-direction:column;gap:5px;padding:11px 0;border-bottom:1px solid var(--border);font-size:12px}.node-picker fieldset{border:1px solid var(--border);border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:10px;max-height:260px;overflow:auto}.node-picker legend{font-size:12px;color:var(--muted);padding:0 5px}.node-option{display:flex;flex-direction:row;align-items:flex-start;gap:9px;margin:0;font-size:13px}.node-option input{width:16px;height:16px;margin:2px 0 0;flex-shrink:0}.node-option small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.entitlement-editor{max-width:650px;max-height:90dvh;overflow:auto}.entitlement-editor>label,.entitlement-editor>.field-row,.entitlement-editor>.check-row,.entitlement-editor>.group-picker,.entitlement-editor>.node-picker{margin-bottom:16px}.entitlement-editor .modal-footer{position:sticky;bottom:-24px;background:var(--surface);padding:16px 0}.empty{display:flex;align-items:center;flex-direction:column;gap:12px}@media(max-width:700px){.plan-stat-grid{grid-template-columns:1fr 1fr}.plan-stat-grid>div:last-child{grid-column:1/-1}.plan-actions{width:100%}.plans-page .page-heading{gap:16px;flex-wrap:wrap}.entitlement-editor{max-height:94dvh}.plan-card{padding:18px}}
.danger-icon{color:var(--danger,#c74747)}
</style>
